stile:
.uscita h2 { margin-top: 2px; }
.quando-uscita { font-size: var(--s1); color: var(--inchiostro) !important; }
.uscita .manca { color: var(--inchiostro) !important; }
.uscita .note { margin: 8px 0 0; padding-left: 18px; font-size: var(--s-1); color: var(--inchiostro-2); display: grid; gap: 4px; }
.fonti-uscita { font-size: var(--s-1) !important; color: var(--inchiostro-3) !important; }
.fonti-uscita a { color: var(--inchiostro-2); }
.mancanti { display: flex; flex-wrap: wrap; gap: 6px 12px; align-items: baseline; }
.mancanti .vai-a, .verdetto .vai-a { background: none; border: 0; padding: 0; color: var(--accento); text-decoration: underline; cursor: pointer; font: inherit; }
.ordinabile th button { all: unset; cursor: pointer; display: block; }
.ordinabile th[aria-sort="descending"] button::after { content: " ↓"; } .ordinabile th[aria-sort="ascending"] button::after { content: " ↑"; }
.confronto td.n { font-family: var(--cifre); font-variant-numeric: tabular-nums; white-space: nowrap; }
.confronto small { color: var(--inchiostro-3); }
.confronto td.n small { display: block; font-family: var(--testo, inherit); }
#d-contributi_anni input, #d-contributi_mesi input, #d-mesi_anno input, #d-nascita_anno input, #d-figli input { max-width: 140px; }
